import path from 'node:path';
import handler,{explicitAudience,allows,eligibleCatalog,validateAnswer,relevantCatalog,singleUnambiguousMatch,isSelfContained,resolveProgramEvents,unmatchedSalientTerms,_clearAnswerCacheForTests} from '../netlify/functions/lhl-chat.mjs';
import {catalog} from '../netlify/lib/catalog.mjs';
import {rules} from '../netlify/lib/rules.mjs';
import {pages,effectivePage} from '../netlify/lib/pages.mjs';
